public class Main {
    static final long LIMIT = 1000;

    static class Account {
        long balance;
        Account(long balance) { this.balance = balance; }
    }

    // Must be all-or-nothing: on any rule failure, neither account changes.
    static void transfer(Account from, Account to, long amount) {
        if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
        if (amount > from.balance) throw new IllegalArgumentException("insufficient funds");
        from.balance -= amount;
        if (to.balance + amount > LIMIT) throw new IllegalArgumentException("limit exceeded");
        to.balance += amount;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = in.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] p = line.split(" ");
            Account a = new Account(Long.parseLong(p[0]));
            Account b = new Account(Long.parseLong(p[1]));
            String result;
            try {
                transfer(a, b, Long.parseLong(p[2]));
                result = "ok";
            } catch (IllegalArgumentException e) {
                result = "rejected";
            }
            System.out.println(result + " " + a.balance + " " + b.balance);
        }
    }
}

