public class Main {
    // Like a Spring Data Slice over ids 1..n: the ids on this page and whether a next page exists.
    static String slice(int n, int page, int size) {
        int start = page * size;
        int end = Math.min(start + size, n);
        String ids = IntStream.rangeClosed(start + 1, end).mapToObj(String::valueOf).collect(Collectors.joining(","));
        boolean hasNext = end <= n;
        return (ids.isEmpty() ? "-" : ids) + " hasNext=" + hasNext;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = in.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            String[] p = line.split(" ");
            System.out.println(slice(Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2])));
